<template>
<header class="site-header"><div class="header-inner">
<button class="menu-btn" aria-label="打开分类导航" @click="drawerOpen=true"><i class="bi bi-list"></i></button>
<router-link class="brand" to="/"><span class="brand-mark">CX</span><span>CAVXX</span></router-link>
<nav class="desktop-nav"><router-link to="/" class="nav-link">首页</router-link><a href="/#latest" class="nav-link" @click.prevent="anchor('latest')">最新</a><a href="/#hot" class="nav-link" @click.prevent="anchor('hot')">热门</a><a href="/#day-hot" class="nav-link" @click.prevent="anchor('day-hot')">今日热门</a><router-link to="/history" class="nav-link">历史</router-link><router-link v-for="c in classes.slice(0,4)" :key="c.type_id" :to="{name:'category',params:{id:c.type_id}}" class="nav-link">{{c.type_name}}</router-link></nav>
<form class="search-box" @submit.prevent="search"><i class="bi bi-search search-icon"></i><input v-model="word" placeholder="搜索影片" aria-label="搜索影片"><button class="search-btn">搜索</button></form>
</div></header>
<div v-if="drawerOpen" class="drawer-mask" @click="drawerOpen=false"></div><aside class="drawer" :class="{open:drawerOpen}"><div class="drawer-header"><b>浏览分类</b><button @click="drawerOpen=false"><i class="bi bi-x-lg"></i></button></div><div class="drawer-body"><router-link class="drawer-item" to="/" @click="drawerOpen=false"><i class="bi bi-house"></i>首页</router-link><router-link class="drawer-item" to="/history" @click="drawerOpen=false"><i class="bi bi-clock-history"></i>观看历史</router-link><div class="drawer-divider">分类</div><router-link v-for="c in classes" :key="c.type_id" class="drawer-item" :to="{name:'category',params:{id:c.type_id}}" @click="drawerOpen=false"><i class="bi bi-collection-play"></i>{{c.type_name}}</router-link></div></aside>
</template>
<script setup>
import {ref,onMounted} from 'vue'
import {useRouter,useRoute} from 'vue-router'
import {getActiveClass} from '../api/cms'
const router=useRouter(),route=useRoute(),word=ref(''),classes=ref([]),drawerOpen=ref(false)
function search(){const wd=word.value.trim();if(wd)router.push({name:'search',query:{wd,page:'1'}})}
function anchor(id){if(route.name!=='home')router.push({name:'home'}).then(()=>setTimeout(()=>document.getElementById(id)?.scrollIntoView({behavior:'smooth'}),80));else document.getElementById(id)?.scrollIntoView({behavior:'smooth'})}
onMounted(async()=>{try{classes.value=await getActiveClass()}catch(e){console.warn('分类加载失败',e)}})
</script>
<style scoped>
.site-header{position:sticky;top:0;z-index:1000;background:#0b0b0fe8;border-bottom:1px solid #ffffff12;backdrop-filter:blur(18px)}.header-inner{width:min(1400px,calc(100% - 32px));min-height:68px;margin:auto;display:flex;align-items:center;gap:12px}.menu-btn{width:38px;height:38px;border:1px solid #ffffff1a;border-radius:10px;background:#17171f;color:#ddd;font-size:19px}.brand{display:flex;align-items:center;gap:8px;color:white;text-decoration:none;font-weight:850}.brand-mark{padding:5px 8px;border-radius:8px;background:linear-gradient(135deg,#ff416d,#ff7894)}.desktop-nav{display:flex;gap:3px;min-width:0;overflow:hidden;margin-left:4px}.nav-link{padding:8px 9px;border-radius:8px;color:#aaa;text-decoration:none;font-size:12px;white-space:nowrap}.nav-link:hover,.nav-link.router-link-active{color:#fff;background:#ffffff0f}.search-box{margin-left:auto;display:flex;align-items:center;width:min(310px,30vw);min-width:170px;height:40px;padding-left:12px;border:1px solid #ffffff17;border-radius:12px;background:#15151b}.search-icon{color:#777}.search-box input{min-width:0;flex:1;border:0;outline:0;background:transparent;color:#fff;padding:0 10px}.search-btn{height:32px;margin-right:4px;padding:0 12px;border:0;border-radius:9px;background:#ff4d73;color:white}.drawer-mask{position:fixed;inset:0;z-index:1098;background:#000b}.drawer{position:fixed;top:0;left:0;z-index:1099;width:290px;max-width:86vw;height:100vh;overflow:auto;background:#111117;transform:translateX(-100%);transition:transform .25s}.drawer.open{transform:translateX(0)}.drawer-header{height:68px;padding:0 18px;display:flex;align-items:center;justify-content:space-between;color:#fff;border-bottom:1px solid #ffffff12}.drawer-header button{border:0;background:transparent;color:#888}.drawer-body{padding:12px}.drawer-item{display:flex;gap:11px;padding:11px 12px;margin:3px 0;border-radius:9px;color:#aaa;text-decoration:none}.drawer-item i{width:18px;color:#ff7894}.drawer-item:hover,.drawer-item.router-link-active{color:#fff;background:#ff4d731f}.drawer-divider{margin:16px 8px 7px;padding-top:12px;border-top:1px solid #ffffff10;color:#666;font-size:10px}@media(max-width:900px){.desktop-nav{display:none}.search-box{width:min(320px,48vw)}}@media(max-width:640px){.header-inner{width:calc(100% - 20px);min-height:60px;gap:9px}.menu-btn{width:36px;height:36px}.search-box{width:auto;flex:1;min-width:0}}
</style>
